define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_29.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e119485","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_29.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e119589","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to the Power Distribution Unit (PDU) when servicing this item in the Integrated System Cabinet (ISC). Applying LOTO ensures a safe environment when working on this part.<\/p>","href":"t_LOTO-for-ISC-Integrated-System-Cabinet_14845718_21.html","attributes":{"data-id":"id_13106290"},"menu":{"hasChildren":false},"tocID":"id_13106290-d46e119693","topics":[]},{"title":"Removing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Removes the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_RemovingTheServiceAccessTrim_17.html","attributes":{"data-id":"id_2002821"},"menu":{"hasChildren":false},"tocID":"id_2002821-d46e119797","topics":[]},{"title":"Removing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Removes the front service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheFrontServiceAccessPanel_16.html","attributes":{"data-id":"id_2002823"},"menu":{"hasChildren":false},"tocID":"id_2002823-d46e119901","topics":[]},{"title":"Removing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Removes the rear service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheRearServiceAccessPanel_15.html","attributes":{"data-id":"id_2002966"},"menu":{"hasChildren":false},"tocID":"id_2002966-d46e120005","topics":[]},{"title":"Removing the Physiological Acquisition Controller (PAC)","shortdesc":"<p class=\"shortdesc\">Remove the Physiological Acquisition Controller (PAC) from the magnet outer electronics.<\/p>","href":"t_RemovingThePhysiologicalAcquisitionControllerPAC.html","attributes":{"data-id":"id_2001563"},"menu":{"hasChildren":false},"tocID":"id_2001563-d46e120109","topics":[]},{"title":"Installing the Physiological Acquisition Controller (PAC)","shortdesc":"<p class=\"shortdesc\">Install a Physiological Acquisition Controller (PAC) at the location indicated.<\/p>","href":"t_InstallingThePhysiologicalAcquisitionControllerPAC.html","attributes":{"data-id":"id_2014236"},"menu":{"hasChildren":false},"tocID":"id_2014236-d46e120213","topics":[]},{"title":"Installing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Installs the rear service access panel onto the magnet enclosure. This panel covers the components mounted on the left-hand side of the magnet.<\/p>","href":"t_InstallingTheRearServiceAccessPanel_15.html","attributes":{"data-id":"id_2002967"},"menu":{"hasChildren":false},"tocID":"id_2002967-d46e120317","topics":[]},{"title":"Installing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Installs the front service access panel onto the magnet enclosure. This panel covers the components mounted on the left-hand side of the magnet.<\/p>","href":"t_InstallingTheFrontServiceAccessPanel_16.html","attributes":{"data-id":"id_2002825"},"menu":{"hasChildren":false},"tocID":"id_2002825-d46e120421","topics":[]},{"title":"Installing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Installs the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_InstallingTheServiceAccessTrim_17.html","attributes":{"data-id":"id_2002822"},"menu":{"hasChildren":false},"tocID":"id_2002822-d46e120526","topics":[]},{"title":"Finalizing the Physiological Acquisition Controller (PAC) replacement","shortdesc":"<p class=\"shortdesc\">This procedure finalizes the Physiological Acquisition Controller (PAC) replacement.<\/p>","href":"t_FinalizingThePhysiologicalAcquisitionControllerPACReplacement.html","attributes":{"data-id":"id_2014237"},"menu":{"hasChildren":false},"tocID":"id_2014237-d46e120630","topics":[]}]});